// calculateSizes retrieves the size of the checkpoint directory and
// the size of the rootfs-diff.tar file from an archive file without unpacking the files.
func (c *checkpointArchive) calculateSizes() error {
	if c.sizesCalculated {
		return nil
	}
	archiveFile, err := os.Open(c.path)
	if err != nil {
		return err
	}
	defer archiveFile.Close()

	// Decompress the archive
	decompressedStream, err := archive.DecompressStream(archiveFile)
	if err != nil {
		return err
	}
	defer decompressedStream.Close()

	// Create a tar reader to read the files from the decompressed archive
	tarReader := tar.NewReader(decompressedStream)

	// Iterate through each file in the archive
	for {
		hdr, err := tarReader.Next()
		if err == io.EOF {
			// End of archive
			break
		}
